function buildCommand() {
  const __args = [['hashcheck'], 'Network Tools', 'Generate hashes of a given text', async ({ sock, from, msg, args }) => {
  const text = args.join(' ');
  if (!text) return sock.sendMessage(from, { text: 'Usage: .hashcheck <text>' }, { quoted: msg });
  const md5 = crypto.createHash('md5').update(text).digest('hex');
  const sha256 = crypto.createHash('sha256').update(text).digest('hex');
  await sock.sendMessage(from, { text: `MD5: ${md5}\nSHA256: ${sha256}` }, { quoted: msg });
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
